/**
 * @name Unsafe Redirect URI construction
 * @description Constructing a redirect URI using unvalidated user input.
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-redirect-uri
 * @tags security
 *       external/cwe/cwe-601
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module UnsafeRedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
     // Look for return values that look like URIs
     exists(DataFlow::CallCfgNode call |
        // Common oauthlib pattern might be constructing URI
        call.getFunction().(DataFlow::ExprNode).asExpr().(Name).getId() = "add_params_to_uri" and
        sink = call.getArg(0) 
     )
  }
}

module UnsafeRedirectFlow = TaintTracking::Global<UnsafeRedirectConfig>;
import UnsafeRedirectFlow::PathGraph

from UnsafeRedirectFlow::PathNode source, UnsafeRedirectFlow::PathNode sink
where UnsafeRedirectFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential unsafe redirect URI construction from $@.", source.getNode(), "user input"

/**
 * @name JWT None Algorithm or Header Injection
 * @description Usage of 'none' algorithm in JWT or allowing user-controlled headers.
 * @kind path-problem
 * @problem.severity error
 * @id py/jwt-injection
 * @tags security
 *       external/cwe/cwe-327
 *       external/cwe/cwe-345
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module JwtInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for algorithm parameter in jwt.decode or similar
    exists(DataFlow::CallCfgNode call |
       call = API::moduleImport("jwt").getMember(["decode", "encode"]).getACall() and
       (
         sink = call.getArgByName("algorithms") or
         sink = call.getArgByName("algorithm") or
         sink = call.getArgByName("headers")
       )
    )
  }
}

module JwtInjectionFlow = TaintTracking::Global<JwtInjectionConfig>;
import JwtInjectionFlow::PathGraph

from JwtInjectionFlow::PathNode source, JwtInjectionFlow::PathNode sink
where JwtInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential JWT injection from $@.", source.getNode(), "user input"
